import { useState } from "react";
import { api } from "../../convex/_generated/api";
import { REGIONS, type Region } from "../regions";
import { median, type Net } from "../lib/stats";
import { describe } from "../lib/errors";
import type { ExitLocation } from "../hooks/useExitLocation";
import { sessionToken } from "../session";
import { runNetTest } from "../lib/netTest";
import { NetworkBlock, type NetState } from "../components/NetworkBlock";
import { Chip, PulseIcon } from "../components/ui";

const IDLE: NetState = { status: "idle" };

// Logs go to the home region (US) so every test is auditable in one place.
const home = REGIONS[0].client;

export function NetworkView({ location, ready }: { location: ExitLocation | null; ready: boolean }) {
  const resetKey = location?.country;
  const [states, setStates] = useState<Record<string, NetState>>({});
  const [running, setRunning] = useState(false);

  // New exit country (VPN switched) → old numbers no longer apply.
  const [key, setKey] = useState(resetKey);
  if (resetKey !== key) {
    setKey(resetKey);
    if (key !== undefined && !running) setStates({});
  }

  const patch = (id: string, next: Partial<NetState>) =>
    setStates((prev) => ({ ...prev, [id]: { ...(prev[id] ?? IDLE), ...next } }));

  const runOne = async (r: Region) => {
    patch(r.id, { status: "running", error: undefined, net: undefined });
    let id;
    try {
      // Rate-limited per user server-side; no log row, no test.
      id = await home.mutation(api.logs.netTestBegin, {
        sessionToken,
        region: r.id,
        country: location?.country,
        colo: location?.colo,
      });
    } catch (e) {
      patch(r.id, { status: "error", error: describe(e) });
      return;
    }
    try {
      const net = await runNetTest(r, (step, n) => patch(r.id, { step, net: n }));
      patch(r.id, { status: "done" });
      await home.mutation(api.logs.netTestFinish, { sessionToken, id, result: summarize(net) });
    } catch (e) {
      patch(r.id, { status: "error", error: describe(e) });
      await home
        .mutation(api.logs.netTestFinish, { sessionToken, id, result: { kind: "failed", error: describe(e) } })
        .catch(() => {});
    }
  };

  const run = async (targets: Region[]) => {
    setRunning(true);
    targets.forEach((r) => patch(r.id, { status: "queued" }));
    // ponytail: one region at a time so the 4 MB echoes don't share bandwidth and skew MB/s
    for (const r of targets) await runOne(r);
    setRunning(false);
  };

  const done = REGIONS.filter((r) => states[r.id]?.status === "done" && states[r.id]?.net?.wsSamples.length);
  const wsOf = (r: Region) => median(states[r.id].net!.wsSamples);
  const fastest = done.length > 1 ? done.reduce((a, b) => (wsOf(a) <= wsOf(b) ? a : b)).id : null;

  return (
    <div className="flex min-h-0 flex-1 flex-col">
      <div className="flex flex-wrap items-center gap-2 border-b border-line px-4 py-2 text-[13px] text-muted">
        <span className="mr-auto">5 WebSocket pings, 5 HTTP pings, then a 128 B and a 4 MB echo, one region at a time.</span>
        <Chip tone="primary" icon={<PulseIcon />} onClick={() => void run(REGIONS)} disabled={running || !ready}>
          {running ? "Testing…" : "Run all regions"}
        </Chip>
      </div>
      {/* 2×2 grid, all 4 regions in one view; capped and centered on large screens. */}
      <main className="mx-auto grid min-h-0 w-full max-w-6xl flex-1 grid-cols-1 gap-3 p-3 md:grid-cols-2 md:grid-rows-2">
        {REGIONS.map((r) => (
          <NetworkBlock
            key={r.id}
            region={r}
            state={states[r.id] ?? IDLE}
            fastest={fastest === r.id}
            onRun={() => void run([r])}
            disabled={running || !ready}
          />
        ))}
      </main>
      <footer className="border-t border-line bg-panel px-4 py-2 text-xs text-muted">
        Full check including DNS and TCP: <code className="text-neutral-300">pnpm run nettest</code>
      </footer>
    </div>
  );
}

const summarize = (net: Required<Net>) => ({
  kind: "done" as const,
  wsMs: median(net.wsSamples),
  httpMs: median(net.httpSamples),
  echoSmallMs: net.echoSmall,
  echoBigMs: net.echoBig,
  mbps: net.mbps,
});
import type { Region } from "../regions";
import { cx, ms, tone } from "../lib/format";
import { median, type Net } from "../lib/stats";
import type { NetStep } from "../lib/netTest";
import { Chip, PulseIcon } from "./ui";

export type NetState = { status: "idle" | "queued" | "running" | "done" | "error"; step?: NetStep; net?: Net; error?: string };

export function NetworkBlock({
  region,
  state,
  fastest,
  onRun,
  disabled,
}: {
  region: Region;
  state: NetState;
  fastest: boolean;
  onRun: () => void;
  disabled: boolean;
}) {
  const { net, step, status } = state;
  const ws = net?.wsSamples.length ? median(net.wsSamples) : undefined;
  const active = (s: NetStep) => status === "running" && step === s;

  return (
    <section
      className={cx(
        "flex min-h-72 flex-col overflow-hidden rounded-lg border bg-panel transition-colors duration-500",
        fastest ? "border-emerald-500/60" : "border-line",
      )}
    >
      <header className="flex items-center gap-2.5 border-b border-line px-4 py-2.5">
        <span className="text-lg leading-none">{region.flag}</span>
        <h2 className="mr-auto text-sm font-medium text-neutral-100 sm:mr-0">{region.label}</h2>
        <span className="mr-auto hidden h-6 items-center whitespace-nowrap rounded-md border border-dashed border-line px-2 font-mono text-xs text-muted sm:inline-flex">
          {region.aws}
        </span>
        {fastest && (
          <span className="inline-flex h-6 items-center rounded-md border border-dashed border-emerald-500/60 px-2 text-xs text-emerald-300">
            fastest
          </span>
        )}
        <span className={cx("font-mono text-xs", status === "running" ? "text-sky-300" : "text-muted")}>
          {status === "queued" ? "queued" : status === "running" ? "testing…" : status === "done" ? "done" : ""}
        </span>
        <Chip icon={<PulseIcon />} onClick={onRun} disabled={disabled}>
          Run
        </Chip>
      </header>

      <div className="flex min-h-0 flex-1 flex-col gap-4 p-4">
        <div>
          <p key={ws} className="font-mono text-3xl tabular-nums text-neutral-100 animate-flash">
            {ws === undefined ? "—" : ms(ws)}
          </p>
          <p className="text-xs text-muted">median WebSocket round trip · {region.city}</p>
        </div>

        <dl className="grid grid-cols-[6rem_1fr_auto] items-center gap-x-3 gap-y-2.5 font-mono text-xs">
          <Row label="WebSocket" active={active("ws")} value={net?.wsSamples.length ? ms(median(net.wsSamples)) : undefined}>
            <Samples values={net?.wsSamples} />
          </Row>
          <Row label="HTTP" active={active("http")} value={net?.httpSamples.length ? ms(median(net.httpSamples)) : undefined}>
            <Samples values={net?.httpSamples} />
          </Row>
          <Row label="Echo 128 B" active={active("echo-small")} value={net?.echoSmall === undefined ? undefined : ms(net.echoSmall)}>
            <Bar running={active("echo-small")} done={net?.echoSmall !== undefined} />
          </Row>
          <Row
            label="Echo 4 MB"
            active={active("echo-big")}
            value={net?.echoBig === undefined ? undefined : `${ms(net.echoBig)} · ${net.mbps!.toFixed(1)} MB/s`}
          >
            <Bar running={active("echo-big")} done={net?.echoBig !== undefined} />
          </Row>
        </dl>
      </div>

      {state.error && <p className="border-t border-line px-4 py-2 text-xs text-red-400">{state.error}</p>}
    </section>
  );
}

function Row({ label, value, active, children }: { label: string; value?: string; active: boolean; children: React.ReactNode }) {
  return (
    <>
      <dt className={cx("transition-colors", active ? "text-sky-300" : "text-muted")}>{label}</dt>
      <dd className="flex min-w-0 flex-wrap gap-1">{children}</dd>
      <dd key={value} className="text-right tabular-nums text-neutral-200 animate-flash">{value ?? "—"}</dd>
    </>
  );
}

// One pill per ping, popping in as each sample lands.
function Samples({ values = [] }: { values?: number[] }) {
  return (
    <>
      {values.map((v, i) => (
        <span key={i} className="flex items-center gap-1 rounded border border-line px-1.5 py-0.5 tabular-nums text-neutral-300 animate-pop">
          <span className={cx("size-1.5 rounded-[1px]", tone(v))} />
          {Math.round(v)}
        </span>
      ))}
    </>
  );
}

function Bar({ running, done }: { running: boolean; done: boolean }) {
  return (
    <span className="h-1 w-full overflow-hidden rounded-full bg-white/5">
      <span
        className={cx(
          "block h-full rounded-full transition-all duration-500",
          done ? "w-full bg-emerald-400" : running ? "w-1/3 animate-pulse bg-sky-400" : "w-0",
        )}
      />
    </span>
  );
}
export type Stats = { n: number; p50: number; p95: number; max: number; total: number };
export type Net = {
  wsSamples: number[];
  httpSamples: number[];
  echoSmall?: number;
  echoBig?: number;
  mbps?: number;
};
export type Results = { insert?: Stats; delete?: Stats };

export const time = async (f: () => Promise<unknown>) => {
  const t = performance.now();
  await f();
  return performance.now() - t;
};

const pct = (sorted: number[], p: number) =>
  sorted[Math.min(sorted.length - 1, Math.floor(sorted.length * p))];

export const median = (xs: number[]) => pct([...xs].sort((a, b) => a - b), 0.5);

export const stats = (lat: number[], total: number): Stats => {
  const s = [...lat].sort((a, b) => a - b);
  return { n: s.length, p50: pct(s, 0.5), p95: pct(s, 0.95), max: s[s.length - 1], total };
};
import { useCallback, useEffect, useState } from "react";
import { REGIONS } from "../regions";

export type ExitLocation = { country: string; colo: string };

// Cloudflare (already in front of every Convex URL) reports where this browser's
// traffic exits. That follows a VPN; Intl's time zone does not (it's an OS setting).
const TRACE_URL = `${REGIONS[0]?.url}/cdn-cgi/trace`;

export function useExitLocation() {
  const [location, setLocation] = useState<ExitLocation | null>(null);
  const [checking, setChecking] = useState(false);

  const detect = useCallback(async () => {
    setChecking(true);
    try {
      const text = await (await fetch(TRACE_URL, { cache: "no-store" })).text();
      const fields = new Map(text.trim().split("\n").map((l) => l.split("=", 2) as [string, string]));
      const next = { country: fields.get("loc") ?? "XX", colo: fields.get("colo") ?? "?" };
      setLocation(next);
    } catch {
      setLocation(null);
    } finally {
      setChecking(false);
    }
  }, []);

  // Check on load, and whenever you come back from switching VPN country.
  useEffect(() => {
    const check = () => void detect();
    const initial = setTimeout(check, 0);
    window.addEventListener("focus", check);
    window.addEventListener("online", check);
    return () => {
      clearTimeout(initial);
      window.removeEventListener("focus", check);
      window.removeEventListener("online", check);
    };
  }, [detect]);

  return { location, checking, detect };
}

import { api } from "../../convex/_generated/api";
import type { Region } from "../regions";
import { time, type Net } from "./stats";

export type NetStep = "ws" | "http" | "echo-small" | "echo-big";
export const ECHO_BIG = 4 * 1024 * 1024;
const SAMPLES = 5;

// Browser half of `npx convex network-test`: same /instance_name and /echo endpoints.
// Standalone (not a hook) so it runs from any tab; reports progress as it goes.
export async function runNetTest(region: Region, onProgress: (step: NetStep, net: Net) => void): Promise<Required<Net>> {
  const net: Net = { wsSamples: [], httpSamples: [] };
  const report = (step: NetStep) => onProgress(step, { ...net, wsSamples: [...net.wsSamples], httpSamples: [...net.httpSamples] });

  report("ws");
  for (let i = 0; i < SAMPLES; i++) {
    net.wsSamples.push(await time(() => region.client.query(api.items.ping, { nonce: Math.random() })));
    report("ws");
  }
  report("http");
  for (let i = 0; i < SAMPLES; i++) {
    net.httpSamples.push(await time(() => fetch(`${region.url}/instance_name`, { cache: "no-store" })));
    report("http");
  }
  report("echo-small");
  const echoSmall = (net.echoSmall = await echo(region, 128));
  report("echo-big");
  const echoBig = (net.echoBig = await echo(region, ECHO_BIG));
  const mbps = (net.mbps = ECHO_BIG / 1e6 / (echoBig / 1000));
  report("echo-big");
  return { ...net, echoSmall, echoBig, mbps };
}

async function echo(region: Region, size: number) {
  const body = new Uint8Array(size);
  // random bytes so a compressing proxy can't inflate throughput
  for (let i = 0; i < size; i += 65536) crypto.getRandomValues(body.subarray(i, i + 65536));
  return time(async () => {
    const res = await fetch(`${region.url}/echo`, { method: "POST", body });
    const got = (await res.arrayBuffer()).byteLength;
    if (got !== size) throw new Error(`echo returned ${got}/${size} bytes`);
  });
}
