// Server-side timings from the Convex dashboard logs for the last N inserts per region.
// Usage: pnpm run server-times [n]   (default 10)
// The browser can't read logs (admin only), so this runs locally with your CLI login.
import { spawn } from "node:child_process";

const N = Number(process.argv[2] ?? 10);
const REGIONS = ["us", "eu", "au", "ca"];
const QUIET_MS = 4000; // `convex logs` never exits: stop once history has stopped arriving

const fetchLogs = (region) =>
  new Promise((resolve, reject) => {
    const p = spawn("convex", ["logs", "--deployment", `dev/${region}`, "--history", "1000", "--jsonl"]);
    let buf = "";
    let timer;
    const done = () => {
      p.kill();
      resolve(buf.split("\n").filter((l) => l.startsWith("{")).map((l) => JSON.parse(l)));
    };
    const arm = () => {
      clearTimeout(timer);
      timer = setTimeout(done, QUIET_MS);
    };
    p.stdout.on("data", (d) => ((buf += d), arm()));
    p.on("error", reject);
    arm();
  });

const ms = (s) => Math.round(s * 1000);
const p50 = (xs) => [...xs].sort((a, b) => a - b)[Math.floor(xs.length / 2)];

const report = (region, events) => {
  const done = events.filter((e) => e.kind === "Completion").sort((a, b) => a.timestamp - b.timestamp);
  const adds = done.filter((e) => e.identifier === "items:add" && e.logLines.length).slice(-N);
  const lists = done.filter((e) => e.identifier === "items:list");
  const rows = adds.map((a, i) => {
    const until = adds[i + 1]?.timestamp ?? Infinity;
    const after = lists.filter((l) => l.timestamp > a.timestamp && l.timestamp <= until);
    const rerun = after.find((l) => !l.cachedResult);
    return {
      key: a.logLines[0].messages[0].replace(/'/g, "").slice(0, 8),
      add: ms(a.executionTime),
      list: rerun ? ms(rerun.executionTime) : undefined,
      executed: after.filter((l) => !l.cachedResult).length,
      cached: after.filter((l) => l.cachedResult).length,
    };
  });

  const out = [`== ${region}: last ${rows.length} inserts (server time, from the dashboard logs)`];
  if (!rows.length) return [...out, "   no items:add with a logged key yet", ""].join("\n");
  out.push("   key       add ms  list ms  list runs  cached");
  for (const r of rows) {
    const cols = [r.key.padEnd(8), String(r.add).padStart(6), String(r.list ?? "—").padStart(7), String(r.executed).padStart(9), String(r.cached).padStart(6)];
    out.push(`   ${cols.join("  ")}`);
  }
  const lists2 = rows.map((r) => r.list).filter((x) => x !== undefined);
  out.push(`   p50: add ${p50(rows.map((r) => r.add))} ms · list ${lists2.length ? p50(lists2) : "—"} ms`, "");
  return out.join("\n");
};

const results = await Promise.all(REGIONS.map(async (r) => report(r, await fetchLogs(r))));
console.log(results.join("\n"));

