import { CartesianGrid, Line, LineChart, XAxis, YAxis } from "recharts";
import { REGIONS } from "../regions";
import { ms } from "../lib/format";
import type { Benches } from "../hooks/benchStore";
import { ChartContainer, ChartTooltip, ChartTooltipContent, type ChartConfig } from "./chart";

const config: ChartConfig = Object.fromEntries(REGIONS.map((r) => [r.id, { label: `${r.flag} ${r.label}`, color: r.color }]));

// One line per region: x = write # in arrival order, y = ms from send until visible here.
// Lines grow live as each write lands (animation off so streaming points don't jitter).
export function LatencyChart({ benches }: { benches: Benches }) {
  const length = Math.max(0, ...REGIONS.map((r) => benches[r.id]?.series.length ?? 0));
  const data = Array.from({ length }, (_, i) => ({
    write: i + 1,
    ...Object.fromEntries(REGIONS.map((r) => [r.id, roundOrUndefined(benches[r.id]?.series[i])])),
  }));

  return (
    <ChartContainer config={config} className="aspect-auto h-full min-h-64 w-full">
      <LineChart data={data} margin={{ top: 12, right: 16, bottom: 4, left: 4 }}>
        <CartesianGrid vertical={false} />
        <XAxis dataKey="write" tickLine={false} axisLine={false} tickMargin={8} minTickGap={24} />
        <YAxis tickLine={false} axisLine={false} width={64} tickFormatter={(v: number) => ms(v)} />
        <ChartTooltip
          content={<ChartTooltipContent labelFormatter={(_, payload) => `Write #${String(payload[0]?.payload?.write ?? "")}`} />}
        />
        {/* No end labels: lines converge and labels collide; the legend cards above + tooltip carry identity. */}
        {REGIONS.map((r) => (
          <Line
            key={r.id}
            dataKey={r.id}
            type="linear"
            stroke={`var(--color-${r.id})`}
            strokeWidth={2}
            dot={false}
            activeDot={{ r: 4, strokeWidth: 2, stroke: "var(--color-background)" }}
            isAnimationActive={false}
          />
        ))}
      </LineChart>
    </ChartContainer>
  );
}

const roundOrUndefined = (v: number | undefined) => (v === undefined ? undefined : Math.round(v));
import { REGIONS } from "../regions";
import { cx, ms } from "../lib/format";
import type { Results } from "../lib/stats";
import { useBenches } from "../hooks/benchStore";
import { LatencyChart } from "../components/LatencyChart";
import { RunControls } from "../components/RunControls";

// One chart: every region's latest insert run, drawn live while it runs.
export function CompareView({
  n,
  setN,
  ready,
  results,
}: {
  n: number;
  setN: (n: number) => void;
  ready: boolean;
  results: Record<string, Results | undefined>;
}) {
  const benches = useBenches();
  const timed = REGIONS.filter((r) => results[r.id]?.insert);
  const fastest =
    timed.length > 1 ? timed.reduce((a, b) => (results[a.id]!.insert!.p50 <= results[b.id]!.insert!.p50 ? a : b)).id : null;
  const empty = REGIONS.every((r) => !benches[r.id]?.series.length);

  return (
    <div className="flex min-h-0 flex-1 flex-col">
      <div className="flex flex-wrap items-center gap-2 border-b border-line px-4 py-2">
        <span className="mr-auto text-[13px] text-muted">Each write's time until it shows up here, by region, in arrival order.</span>
        <RunControls n={n} setN={setN} ready={ready} />
      </div>

      <main className="mx-auto flex min-h-0 w-full max-w-6xl flex-1 flex-col gap-3 p-3">
        {/* Legend with live numbers; color follows the region, never its rank. */}
        <ul className="grid grid-cols-2 gap-3 md:grid-cols-4">
          {REGIONS.map((r) => {
            const b = benches[r.id];
            const ins = results[r.id]?.insert;
            const running = b?.busy === "insert" && b.progress;
            return (
              <li
                key={r.id}
                className={cx(
                  "flex flex-col gap-1 rounded-lg border bg-panel px-3 py-2 transition-colors duration-500",
                  fastest === r.id ? "border-emerald-500/60" : "border-line",
                )}
              >
                <span className="flex items-center gap-2 text-[13px] text-neutral-200">
                  <span className="h-0.5 w-4 rounded-full" style={{ backgroundColor: r.color }} aria-hidden />
                  {r.flag} {r.label}
                  {fastest === r.id && <span className="ml-auto text-xs text-emerald-300">fastest</span>}
                </span>
                <span className="font-mono text-xs tabular-nums text-muted">
                  {running ? (
                    `${b.progress!.done} / ${b.progress!.total} seen…`
                  ) : ins ? (
                    <>
                      median <b className="font-normal text-neutral-100">{ms(ins.p50)}</b> · all {ms(ins.total)}
                    </>
                  ) : (
                    "no run yet"
                  )}
                </span>
              </li>
            );
          })}
        </ul>

        <section className="relative flex min-h-0 flex-1 flex-col rounded-lg border border-line bg-panel p-4">
          <header className="mb-2 flex items-baseline justify-between gap-3">
            <h2 className="text-sm font-medium text-neutral-100">Time until each write shows up</h2>
            <span className="text-xs text-muted">x: write # (arrival order) · y: ms</span>
          </header>
          <div className="min-h-0 flex-1">
            <LatencyChart benches={benches} />
          </div>
          {empty && (
            <p className="pointer-events-none absolute inset-0 grid place-items-center text-[13px] text-muted">
              Pick N and hit Insert to draw the lines live.
            </p>

